<?php

/* @autogenerated */
declare(strict_types=1);

namespace Civi\Lughauth\Features\Oidc\WebAuthn\Infrastructure\Service;

use CBOR\Decoder;
use CBOR\StringStream;
use Civi\Lughauth\Features\Oidc\WebAuthn\Domain\Exception\WebAuthnException;

/**
 * Handles low-level WebAuthn cryptographic verification.
 *
 * Uses spomky-labs/cbor-php (bundled with web-auth/webauthn-framework) for CBOR
 * decoding and PHP's openssl extension for signature verification.
 *
 * Supported algorithms:
 *   - ES256 (alg = -7): ECDSA P-256 / SHA-256
 *   - RS256 (alg = -257): RSASSA-PKCS1-v1_5 / SHA-256
 */
class WebAuthnVerifier
{
    private const ALG_ES256 = -7;
    private const ALG_RS256 = -257;

    private const COSE_KTY_EC2 = 2;
    private const COSE_KTY_RSA = 3;
    private const COSE_CRV_P256 = 1;

    private const FLAG_UP = 0x01;
    private const FLAG_UV = 0x04;
    private const FLAG_AT = 0x40;

    /**
     * Verifies an attestation response (registration).
     *
     * @param array  $clientCredential Decoded JSON from the browser (id, rawId, response, type)
     * @param string $storedChallenge  Base64url-encoded challenge stored server-side
     * @param string $expectedOrigin   e.g. "https://app.example.com"
     * @param string $rpId             e.g. "app.example.com"
     *
     * @return array{credentialId: string, publicKey: string, signCount: int, aaguid: string|null, transports: array|null}
     */
    public function verifyRegistration(
        array $clientCredential,
        string $storedChallenge,
        string $expectedOrigin,
        string $rpId,
    ): array {
        $response = $clientCredential['response'] ?? [];

        $clientDataRaw = $this->base64urlDecode($response['clientDataJSON'] ?? '');
        $clientData = json_decode($clientDataRaw, true, 512, JSON_THROW_ON_ERROR);

        $this->assertClientData($clientData, 'webauthn.create', $storedChallenge, $expectedOrigin);

        $attestationObjectRaw = $this->base64urlDecode($response['attestationObject'] ?? '');
        $attestation = $this->cborDecode($attestationObjectRaw);

        $authDataRaw = $attestation['authData'] ?? '';
        if (is_object($authDataRaw)) {
            $authDataRaw = (string) $authDataRaw;
        }

        $this->verifyRpIdHash($authDataRaw, $rpId);
        $flags = ord($authDataRaw[32]);

        if (!($flags & self::FLAG_UP)) {
            throw WebAuthnException::verificationFailed('user presence not set');
        }

        $signCount = $this->extractSignCount($authDataRaw);

        if (!($flags & self::FLAG_AT)) {
            throw WebAuthnException::verificationFailed('no attested credential data');
        }

        ['credentialId' => $credentialId, 'publicKey' => $publicKeyPem, 'aaguid' => $aaguid] =
            $this->extractAttestedCredentialData($authDataRaw);

        $transports = $response['transports'] ?? null;

        return [
            'credentialId' => $credentialId,
            'publicKey' => $publicKeyPem,
            'signCount' => $signCount,
            'aaguid' => $aaguid,
            'transports' => is_array($transports) ? $transports : null,
        ];
    }

    /**
     * Verifies an assertion response (authentication).
     *
     * @param array  $clientCredential  Decoded JSON from the browser
     * @param string $storedChallenge   Base64url-encoded challenge stored server-side
     * @param string $expectedOrigin    e.g. "https://app.example.com"
     * @param string $rpId              e.g. "app.example.com"
     * @param string $storedPublicKey   PEM-encoded public key stored during registration
     * @param int    $storedSignCount   Current sign count for the credential
     *
     * @return int New sign count to persist
     */
    public function verifyAssertion(
        array $clientCredential,
        string $storedChallenge,
        string $expectedOrigin,
        string $rpId,
        string $storedPublicKey,
        int $storedSignCount,
    ): int {
        $response = $clientCredential['response'] ?? [];

        $clientDataRaw = $this->base64urlDecode($response['clientDataJSON'] ?? '');
        $clientData = json_decode($clientDataRaw, true, 512, JSON_THROW_ON_ERROR);

        $this->assertClientData($clientData, 'webauthn.get', $storedChallenge, $expectedOrigin);

        $authDataRaw = $this->base64urlDecode($response['authenticatorData'] ?? '');
        $this->verifyRpIdHash($authDataRaw, $rpId);

        $flags = ord($authDataRaw[32]);
        if (!($flags & self::FLAG_UP)) {
            throw WebAuthnException::verificationFailed('user presence not set');
        }

        $signCount = $this->extractSignCount($authDataRaw);
        if ($signCount !== 0 && $signCount <= $storedSignCount) {
            throw WebAuthnException::replayAttack();
        }

        $signatureRaw = $this->base64urlDecode($response['signature'] ?? '');
        $verificationData = $authDataRaw . hash('sha256', $clientDataRaw, true);

        $pubKey = openssl_pkey_get_public($storedPublicKey);
        if ($pubKey === false) {
            throw WebAuthnException::verificationFailed('cannot load public key');
        }

        $verified = openssl_verify($verificationData, $signatureRaw, $pubKey, OPENSSL_ALGO_SHA256);
        if ($verified !== 1) {
            throw WebAuthnException::verificationFailed('signature verification failed');
        }

        return $signCount;
    }

    private function assertClientData(
        array $clientData,
        string $expectedType,
        string $storedChallenge,
        string $expectedOrigin,
    ): void {
        if (($clientData['type'] ?? '') !== $expectedType) {
            throw WebAuthnException::verificationFailed('unexpected clientData type');
        }
        if (($clientData['challenge'] ?? '') !== $storedChallenge) {
            throw WebAuthnException::verificationFailed('challenge mismatch');
        }
        if (($clientData['origin'] ?? '') !== $expectedOrigin) {
            throw WebAuthnException::verificationFailed('origin mismatch');
        }
    }

    private function verifyRpIdHash(string $authData, string $rpId): void
    {
        if (strlen($authData) < 37) {
            throw WebAuthnException::verificationFailed('authenticatorData too short');
        }
        $rpIdHash = substr($authData, 0, 32);
        if (!hash_equals(hash('sha256', $rpId, true), $rpIdHash)) {
            throw WebAuthnException::verificationFailed('rpId hash mismatch');
        }
    }

    private function extractSignCount(string $authData): int
    {
        return (int) unpack('N', substr($authData, 33, 4))[1];
    }

    private function extractAttestedCredentialData(string $authData): array
    {
        $offset = 37;

        $aaguidBytes = substr($authData, $offset, 16);
        $aaguid = vsprintf('%s-%s-%s-%s-%s', str_split(bin2hex($aaguidBytes), 4) + [
            0 => substr(bin2hex($aaguidBytes), 0, 8),
            1 => substr(bin2hex($aaguidBytes), 8, 4),
            2 => substr(bin2hex($aaguidBytes), 12, 4),
            3 => substr(bin2hex($aaguidBytes), 16, 4),
            4 => substr(bin2hex($aaguidBytes), 20, 12),
        ]);
        $offset += 16;

        $credIdLen = (int) unpack('n', substr($authData, $offset, 2))[1];
        $offset += 2;

        $credentialIdBytes = substr($authData, $offset, $credIdLen);
        $credentialId = $this->base64urlEncode($credentialIdBytes);
        $offset += $credIdLen;

        $coseKeyRaw = substr($authData, $offset);
        $coseKey = $this->cborDecode($coseKeyRaw);

        $publicKeyPem = $this->coseKeyToPem($coseKey);

        return [
            'credentialId' => $credentialId,
            'publicKey' => $publicKeyPem,
            'aaguid' => $aaguid,
        ];
    }

    private function coseKeyToPem(array $coseKey): string
    {
        $kty = $coseKey[1] ?? null;

        if ($kty === self::COSE_KTY_EC2) {
            return $this->ec2CoseKeyToPem($coseKey);
        }

        if ($kty === self::COSE_KTY_RSA) {
            return $this->rsaCoseKeyToPem($coseKey);
        }

        throw WebAuthnException::verificationFailed('unsupported COSE key type: ' . $kty);
    }

    private function ec2CoseKeyToPem(array $coseKey): string
    {
        $crv = $coseKey[-1] ?? null;
        if ($crv !== self::COSE_CRV_P256) {
            throw WebAuthnException::verificationFailed('only P-256 curve supported');
        }

        $x = $this->coseBytes($coseKey[-2] ?? null);
        $y = $this->coseBytes($coseKey[-3] ?? null);

        if (strlen($x) !== 32 || strlen($y) !== 32) {
            throw WebAuthnException::verificationFailed('invalid EC2 key coordinates');
        }

        // SubjectPublicKeyInfo DER for EC P-256
        $ecPublicKeyOid = "\x06\x07\x2a\x86\x48\xce\x3d\x02\x01";
        $p256Oid = "\x06\x08\x2a\x86\x48\xce\x3d\x03\x01\x07";
        $algoSeq = "\x30" . $this->derLen(strlen($ecPublicKeyOid) + strlen($p256Oid)) . $ecPublicKeyOid . $p256Oid;
        $point = "\x04" . $x . $y;
        $bitString = "\x03" . $this->derLen(strlen($point) + 1) . "\x00" . $point;
        $spki = "\x30" . $this->derLen(strlen($algoSeq) + strlen($bitString)) . $algoSeq . $bitString;

        return "-----BEGIN PUBLIC KEY-----\n" . chunk_split(base64_encode($spki), 64, "\n") . "-----END PUBLIC KEY-----\n";
    }

    private function rsaCoseKeyToPem(array $coseKey): string
    {
        $n = $this->coseBytes($coseKey[-1] ?? null);
        $e = $this->coseBytes($coseKey[-2] ?? null);

        // Ensure positive integers (prepend 0x00 if high bit set)
        if (ord($n[0]) > 0x7f) {
            $n = "\x00" . $n;
        }
        if (ord($e[0]) > 0x7f) {
            $e = "\x00" . $e;
        }

        $nInt = "\x02" . $this->derLen(strlen($n)) . $n;
        $eInt = "\x02" . $this->derLen(strlen($e)) . $e;
        $seqInner = "\x30" . $this->derLen(strlen($nInt) + strlen($eInt)) . $nInt . $eInt;

        $rsaOid = "\x06\x09\x2a\x86\x48\x86\xf7\x0d\x01\x01\x01\x05\x00";
        $algoSeq = "\x30" . $this->derLen(strlen($rsaOid)) . $rsaOid;
        $bitString = "\x03" . $this->derLen(strlen($seqInner) + 1) . "\x00" . $seqInner;
        $spki = "\x30" . $this->derLen(strlen($algoSeq) + strlen($bitString)) . $algoSeq . $bitString;

        return "-----BEGIN PUBLIC KEY-----\n" . chunk_split(base64_encode($spki), 64, "\n") . "-----END PUBLIC KEY-----\n";
    }

    private function coseBytes(mixed $value): string
    {
        if (is_string($value)) {
            return $value;
        }
        if (is_object($value) && method_exists($value, '__toString')) {
            return (string) $value;
        }
        throw WebAuthnException::verificationFailed('invalid COSE key bytes');
    }

    private function derLen(int $len): string
    {
        if ($len < 128) {
            return chr($len);
        }
        if ($len < 256) {
            return "\x81" . chr($len);
        }
        return "\x82" . chr($len >> 8) . chr($len & 0xff);
    }

    private function cborDecode(string $raw): array
    {
        $decoded = Decoder::create()->decode(StringStream::create($raw));
        $normalized = $decoded->normalize();
        return is_array($normalized) ? $normalized : [];
    }

    private function base64urlDecode(string $input): string
    {
        $padded = str_pad(strtr($input, '-_', '+/'), (int) ceil(strlen($input) / 4) * 4, '=');
        $decoded = base64_decode($padded, true);
        if ($decoded === false) {
            throw WebAuthnException::verificationFailed('invalid base64url encoding');
        }
        return $decoded;
    }

    private function base64urlEncode(string $input): string
    {
        return rtrim(strtr(base64_encode($input), '+/', '-_'), '=');
    }
}
